const _ = Symbol('placeholder');

function curry(fn) {
  const arity = fn.length;

  return function curried(...args) {
    // Replace placeholders with new args
    const filled = args.slice();
    const pending = args.filter(a => a === _).length;

    if (filled.length - pending >= arity) {
      return fn(...filled.filter(a => a !== _));
    }

    return function(...more) {
      const merged = filled.map(a => a === _ && more.length ? more.shift() : a);
      return curried(...merged, ...more);
    };
  };
}

const add3 = curry((a, b, c) => a + b + c);
add3(1)(2)(3);          // 6
add3(1, 2)(3);          // 6
const addTo10 = add3(_, _, 10); // placeholder
addTo10(1)(2);          // 13

